export const isCssGradient = (v) => /^\s*(linear|radial|conic)-gradient\s*\(/i.test(v);
// 'none' is a literal passthrough (not a url()) — used when a canvas
// wallpaper is active, since the live rendering comes from a background
// iframe instead and the grid's own background must stay transparent so
// that iframe (sitting behind it) shows through.
export const layoutCss = (grid, wallpaperUrl) => `
    .layout-default {
        height: 100%;
        display: grid;
        grid-template-columns: ${grid.columns};
        grid-template-rows: ${grid.rows};
        grid-auto-flow: row;
        grid-template-areas: ${grid.areas};
        background-image: ${isCssGradient(wallpaperUrl) || wallpaperUrl === 'none' ? wallpaperUrl : `url(${wallpaperUrl})`};
        background-repeat: no-repeat;
        background-size: cover;
    }
    .header {
        grid-area: header;
    }
    .left-nav {
        grid-area: left-nav;
    }
    .content-area {
        grid-area: content-area;
        min-height: 0;
        min-width: 0;
        overflow: hidden;
    }
    .right-nav {
        grid-area: right-nav;
    }
    .footer {
        grid-area: footer;
    }
    .footer,
    .toolbar {
        display: none;
    }
    body.vfs-dock-occupy .layout-default {
        box-sizing: border-box;
        padding-bottom: var(--vfs-dock-height, 0px);
    }
`;
